@command("RENAME", 3, write=True)
def rename(ctx, args):
    src, dst = args[1], args[2]
    value = ctx.ks.lookup(src)
    if value is None:
        raise RespError("ERR no such key")
    when = ctx.ks.expires.get(src)
    ctx.ks.delete(src)
    ctx.ks.store(dst, value)
    if when is not None:
        ctx.ks.set_expire_at(dst, when)
    return OK

