            self.waiters.remove(w)

# illustrative (not in repo): Redis-style LFU counter
LFU_INIT, LOG_FACTOR, DECAY_MIN = 5, 10, 1

def lfu_touch(counter: int, last_min: int, now_min: int) -> tuple[int, int]:
    periods = (now_min - last_min) // DECAY_MIN
    counter = max(counter - periods, 0)                 # decay first
    if counter < 255:
        base = max(counter - LFU_INIT, 0)
        if random.random() < 1.0 / (base * LOG_FACTOR + 1):
            counter += 1                                # logarithmic increment
    return counter, now_min

