# solution: tests/test_expiry_eviction.py
def test_allkeys_random_evicts_until_fits():
    ks = Keyspace()
    for i in range(10):
        ks.store(b"k%d" % i, b"x" * 100)          # 2 + 64 + 100 = 166 bytes each
    limit = ks.used_memory // 2                   # 830
    assert ks.evict_until_fits(limit, EvictionPolicy.ALLKEYS_RANDOM)
    assert ks.used_memory <= limit and ks.stats.evicted_keys == 5
    assert len(ks._all) == len(ks.data) == 5
